```python
def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()
        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or not domain
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return local + "@" + domain

    def normalize_phone(value):
        value = value or ""
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)

        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = (value or "").strip()

        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value[:5]

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError("Unsupported updated value: {!r}".format(value))

    def is_opted_out(value):
        return (value or "").strip().lower() in {"y", "yes", "true", "1"}

    normalized_rows = []

    for index, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))

        # Rows without either valid contact method are excluded before matching.
        if not email and not phone:
            continue

        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row.get("tags", "") or "")
            if tag.strip()
        }

        normalized_rows.append({
            "index": index,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row.get("zip", "")),
            "tags": tags,
            "opted_out": is_opted_out(row.get("opted_out", "")),
            "updated_dt": parse_updated(row["updated"]),
            "source": (row.get("source", "") or "").strip().lower(),
        })

    count = len(normalized_rows)
    parent = list(range(count))
    rank = [0] * count

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(left, right):
        left_root = find(left)
        right_root = find(right)

        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    by_email = {}
    by_phone_and_last_name = {}

    for position, row in enumerate(normalized_rows):
        if row["email"]:
            previous = by_email.get(row["email"])
            if previous is None:
                by_email[row["email"]] = position
            else:
                union(position, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = by_phone_and_last_name.get(key)
            if previous is None:
                by_phone_and_last_name[key] = position
            else:
                union(position, previous)

    groups = {}
    for position, row in enumerate(normalized_rows):
        groups.setdefault(find(position), []).append(row)

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(row["index"] for row in group),
    )

    def select_field(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda row: (
                row["source"].casefold() == "manual",
                row["updated_dt"],
                -row["index"],
            ),
        )
        return best[field]

    result = []

    for group in ordered_groups:
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest_updated = max(row["updated_dt"] for row in group)

        result.append({
            "first_name": select_field(group, "first_name"),
            "last_name": select_field(group, "last_name"),
            "zip": select_field(group, "zip"),
            "email": select_field(group, "email"),
            "phone": select_field(group, "phone"),
            "source": select_field(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return result
